using System;using System.Collections.Generic;using Ashfall.Core;using Ashfall.Integration.Playable.Networking;using Ashfall.Integration.Playable.Match;using Ashfall.Integration.Playable.UI;
// Adopt alongside D84/D85; Pickup2ResetInventory is the extracted production round-start guard.
// Lobby custody, retention, resources, preview, drops and grants are production code. The native
// reset's inventory clear is projected into a list; Unity hands/art/Physics are not executed.
partial class LobbyCases {
#if !PICKUP2_EXTRACT_GUARD
 static bool Pickup2ResetInventory(bool resetInventory,bool retaining){return R26InventorySlots.ResetLocal(resetInventory,retaining);}
#endif
 static readonly string Pickup2Hash=new string('b',64);
 static void Pickup2Pump(Pair p){for(int i=0;i<6;i++)KeepRaw(p,Pickup2Hash,0,8);}
 static R24LanLobby Pickup2Actor(Pair p,bool host){return host?p.Host:p.Client;}
 static Float3 Pickup2At(bool host){return new Float3(host?8.3f:.3f,1.2f,.4f);}
 static void Pickup2Bag(Pair p,bool host,string id,int capacity){var actor=Pickup2Actor(p,host);Need(p.Host.RegisterSharedSupply(id,"backpack",1,Pickup2At(host)),"Register backpack "+id);Pickup2Pump(p);Need(actor.RequestSupply(id,1),"Request backpack "+id);Pickup2Pump(p);R24LanResourcesState r;Need(actor.TryReadOwnResources(out r)&&actor.OwnsResources(r)&&r.Capacity==capacity,"Receipt capacity "+capacity);}
 static void Pickup2Gun(Pair p,bool host,string id,string profile){Need(p.Host.RegisterWorldWeapon(id,profile,1,Pickup2At(host)),"Register "+profile);Pickup2Pump(p);Need(Pickup2Actor(p,host).RequestLoot(id,1,false,new Float3()),"Submit "+id);Pickup2Pump(p);R24LanLootState row;Need(p.Host.TryReadLoot(id,out row)&&row.Owner==Pickup2Actor(p,host).OwnActor,"Custody "+id);}
 static R23OwnedLoadout Pickup2UI(List<string> weapons,int capacity){var rows=new List<R23LoadoutOption>();foreach(string id in weapons)rows.Add(new R23LoadoutOption(id,id,"",1,false,1));return new R23OwnedLoadout(rows,capacity);}
 static void Pickup2NextRound(Pair p){var rules=p.Host.SelectedMap.Rules;p.Now=p.Host.SelectedMap.StartsAt+rules.TimeLimit+.1;p.Tick();Need(p.Host.SelectedMap.Round==2&&p.Host.ReportMapLoaded(Pickup2Hash),"Same-map retained epoch");for(int i=0;i<4;i++)p.Tick();Need(p.Client.ReportMapLoaded(Pickup2Hash),"Guest loads retained epoch");for(int i=0;i<5;i++)p.Tick();p.Now=p.Host.SelectedMap.StartsAt+.1;p.Host.Tick(p.Now);p.Client.Tick(p.Now);Need(p.Client.RequestSpawn(),"Retained guest spawn");for(int i=0;i<4;i++)p.Tick();Need(p.Host.RequestSpawn(),"Retained host spawn");Pickup2Pump(p);}
 static void Pickup2RetainedSlot(bool host){using(var p=new Pair()){p.Host.BindCombatWorld(delegate(Float3 o,Float3 v,float r){return r;});StartRound(p,new HazardWorld(),R24PlayableMatchRules.ForPreset("free_for_all","range").With("zone_enabled",false).With("protection",0f).With("rounds",2).With("retain_inventory",true),Pickup2Hash);Pickup2Pump(p);var actor=Pickup2Actor(p,host);var local=new List<string>(new[]{"cx4","px4","m1014"});string session=actor.SessionId,map=actor.MapId;Pickup2Bag(p,host,"pickup2/first",4);Pickup2Gun(p,host,"pickup2/carried","awp");local.Add("pickup2/carried");Pickup2NextRound(p);
  bool retaining=R26InventorySlots.RetainsLocal(true,actor.SessionId,actor.MapId,session,map);Need(retaining,"Prepared inventory is same-map retained");bool reset=Pickup2ResetInventory(true,retaining);
  if(reset)local=new List<string>(new[]{"cx4","px4","m1014"}); // exact owned-list outcome of native Gameplay.ResetRound
  R24LanResourcesState resources;Need(actor.TryReadOwnResources(out resources)&&resources.Capacity==4,"Host retained backpack balance");var ui=Pickup2UI(local,resources.Capacity);bool free=R26InventorySlots.HasRoom(ui.Capacity,ui.Count,0,0);string why;Need(p.Host.RegisterWorldWeapon("pickup2/last","katana",1,Pickup2At(host)),"World sword after transition");Pickup2Pump(p);
  if(reset){Need(ui.Slot(3)==null&&free,"BEFORE: UI shows one free slot");Need(!p.Host.PreviewOwnLoot("pickup2/last",1,false,out why)||!host,"BEFORE host preview full (guest control checked by command)");actor.RequestLoot("pickup2/last",1,false,new Float3());Pickup2Pump(p);R24LanLootState row;Need(p.Host.TryReadLoot("pickup2/last",out row)&&row.Owner==""&&p.Host.LastPickupRejection=="slots-full","BEFORE: last displayed slot refused");Pickup2Bag(p,host,"pickup2/second",5);Need(actor.RequestLoot("pickup2/last",1,false,new Float3()),"After another backpack request");Pickup2Pump(p);Need(p.Host.TryReadLoot("pickup2/last",out row)&&row.Owner==actor.OwnActor,"BEFORE: one more backpack makes pickup work");Console.WriteLine("REPRO "+(host?"host":"guest")+": UI 3/4, host custody 4/4 -> slots-full; backpack 5 -> accepted");}
  else{Need(ui.Count==4&&ui.Slot(3)!=null&&!free,"AFTER: retained UI shows every host-owned weapon");if(host){Need(!actor.PreviewOwnLoot("pickup2/last",1,false,out why)&&why=="slots-full","Full preview agrees with UI");Need(actor.PreviewOwnLoot("pickup2/last",1,true,out why),"Inline swap preview admits all non-slot rules");}long sequence=actor.CommandSequence;Need(actor.RequestLoot("cx4",1,true,Pickup2At(host))&&actor.RequestLoot("pickup2/last",1,false,new Float3()),"Full inventory swaps drop before grant");if(!host)Need(actor.CommandSequence==sequence+2,"Guest swap stays ordered");Pickup2Pump(p);R24LanLootState row;Need(p.Host.TryReadLoot("pickup2/last",out row)&&row.Owner==actor.OwnActor,"Full displayed slot swaps successfully");local.Remove("cx4");local.Add("pickup2/last");Pickup2Bag(p,host,"pickup2/second",5);Need(R26InventorySlots.HasRoom(5,local.Count,0,0),"One genuine free slot after next backpack");Pickup2Gun(p,host,"pickup2/fifth","cx4");local.Add("pickup2/fifth");Need(!R26InventorySlots.HasRoom(5,local.Count,0,0)&&Pickup2UI(local,5).Slot(4)!=null,"Last slot now filled in custody and UI");Console.WriteLine("FIX "+(host?"host":"guest")+": retained UI 4/4, inline/ordered swap accepted; backpack 5 -> fifth weapon accepted");}
 }}
 static void Pickup2LastSlots(bool host,int capacity,string profile){using(var p=new Pair()){R26Setup(p,Pickup2Hash);var actor=Pickup2Actor(p,host);for(int cap=4;cap<=capacity;cap++)Pickup2Bag(p,host,"pickup2/bag/"+cap,cap);for(int n=3;n<capacity;n++){Need(R26InventorySlots.HasRoom(capacity,n,0,0),"Local/UI reports real vacancy");Pickup2Gun(p,host,"pickup2/fill/"+n,profile);}Need(!R26InventorySlots.HasRoom(capacity,capacity,0,0),"Shared rule full after final grant");Need(p.Host.RegisterWorldWeapon("pickup2/overflow","cx4",1,Pickup2At(host)),"Overflow gun");Pickup2Pump(p);actor.RequestLoot("pickup2/overflow",1,false,new Float3());Pickup2Pump(p);R24LanLootState row;Need(p.Host.TryReadLoot("pickup2/overflow",out row)&&row.Owner==""&&p.Host.LastPickupRejection=="slots-full","Capacity exact; no extra grant");}}
 static void Pickup2MixedGrenades(bool host){using(var p=new Pair()){R26Setup(p,Pickup2Hash);var actor=Pickup2Actor(p,host);Pickup2Bag(p,host,"pickup2/flashbag",4);for(int n=0;n<1;n++){string id="pickup2/flash/"+n;Need(p.Host.RegisterSharedGrenade(id,"flash",Pickup2At(host)),"Flash world");Pickup2Pump(p);Need(actor.RequestGrenade(id,1,0,new Float3()),"Flash request");Pickup2Pump(p);R24LanGrenadeState row;Need(p.Host.TryReadGrenade(id,out row)&&row.Owner==actor.OwnActor,"Flash stack custody");}Need(!R26InventorySlots.HasRoom(4,3,0,1),"One flash occupies one slot");Pickup2Bag(p,host,"pickup2/flashbag2",5);Need(R26InventorySlots.HasRoom(5,3,0,1),"Mixed inventory has one true vacancy");Pickup2Gun(p,host,"pickup2/mixed-last","katana");}}
 internal static void Pickup2Run(){int before=checks;Pickup2RetainedSlot(true);Pickup2RetainedSlot(false);foreach(bool host in new[]{true,false}){foreach(int capacity in new[]{4,5,6})foreach(string profile in new[]{"cx4","katana","grapple"})Pickup2LastSlots(host,capacity,profile);Pickup2MixedGrenades(host);}Need(R26InventorySlots.ResetLocal(true,false)&&!R26InventorySlots.ResetLocal(false,false)&&!R26InventorySlots.ResetLocal(true,true),"Fresh round resets; retained round preserves");Need(!R26InventorySlots.RetainsLocal(true,"new-session","range","old-session","range")&&!R26InventorySlots.RetainsLocal(true,"session","new-map","session","old-map")&&!R26InventorySlots.RetainsLocal(false,"session","range","session","range"),"Fresh session, different map and explicit reset are not retained");Console.WriteLine("PASS "+(checks-before)+" PICKUP2 observations (lobby/transport/UI CPU; native reset effects projected)");}
}
